-- ============================================================
-- Drop the now-unused rank 2 override
-- ============================================================
-- 30057 was Improved Howl of Terror rank 2.  Fel Interdiction is a 1-point
-- talent, so the id is no longer listed by talent 1668 and reverts to its
-- untouched Blizzard row.  A character who had spent a point on rank 2 keeps
-- the orphaned spell until its next talent reset.

DELETE FROM `alonecraft_spell_dbc` WHERE `ID` = 30057;


-- ============================================================
-- spell_proc: Drain Soul clears a stack of Mark of Gul'dan
-- ============================================================
-- SpellFamilyName 5 (Warlock), SpellFamilyMask0 16384 (0x4000 = Drain Soul).
-- ProcFlags 327680 = 0x50000 = DONE_SPELL_MAGIC_DMG_CLASS_NEG | DONE_PERIODIC.
-- DONE_PERIODIC is the half that matters: Drain Soul's damage is
-- SPELL_AURA_PERIODIC_DAMAGE channel ticks, so one stack clears per tick
-- (about 5 over a full channel).
--
-- AttributesMask stays 0 deliberately.  PROC_ATTR_TRIGGERED_CAN_PROC (0x2) is
-- only needed when the triggering damage comes from a spell cast as
-- triggered; periodic-damage ticks carry no Spell object and skip
-- Aura::IsProcTriggeredOnEvent's check entirely.
--
-- SpellTypeMask 1 = PROC_SPELL_TYPE_DAMAGE, SpellPhaseMask 2 = PHASE_HIT.
-- SpellPhaseMask MUST be non-zero or the proc silently never fires.

DELETE FROM `spell_proc` WHERE `SpellId` = 30054;
